-- Check how many races have pole position data, and look at the format of q3_r times
SELECT COUNT(DISTINCT rbind) as num_races_with_qualifying FROM qualifying;
SELECT COUNT(DISTINCT CASE WHEN px_pos = 1 THEN rbind END) as num_pole_positions FROM qualifying;

-- Check: how many races have at least one driver with q3_r?
SELECT COUNT(DISTINCT rbind) as races_with_q3 FROM qualifying WHERE q3_r IS NOT NULL;
-- How many races have px_pos = 1?
SELECT COUNT(DISTINCT rbind) as races_with_pole FROM qualifying WHERE px_pos = 1;

-- Test LEAST with NULLs
SELECT LEAST(NULL, 60.5, 70.0) as result;
SELECT LEAST(COALESCE(NULL, 999), 60.5, 70.0) as result;

-- Count distinct drivers who have at least one non-NULL lap time
SELECT COUNT(DISTINCT pilotrec) FROM qualifying 
WHERE q1_r IS NOT NULL OR q2_r IS NOT NULL OR q3_r IS NOT NULL;

-- Find drivers with NO lap times at all
SELECT pilotrec FROM qualifying 
WHERE q1_r IS NULL AND q2_r IS NULL AND q3_r IS NULL;

-- Get DISTINCT drivers with no lap times
SELECT DISTINCT pilotrec FROM qualifying 
WHERE q1_r IS NULL AND q2_r IS NULL AND q3_r IS NULL;

-- Count distinct drivers with no lap times
SELECT COUNT(DISTINCT pilotrec) FROM qualifying 
WHERE q1_r IS NULL AND q2_r IS NULL AND q3_r IS NULL;
